import fse from 'fs-extra';
import { getAsyncApiFilesFromConfig } from '../read/getAsyncApiFilesFromConfig.js';
import { generateAsyncApiFromDocsConfig } from './generateAsyncApiFromDocsConfig.js';
import { assertNoGeneratedRouteCollisions } from './generatedRouteCollisions.js';
export const generateAsyncApiDivisions = async (docsConfig, asyncApiFiles, targetDir, localSchema, graphqlPages, writeFiles = true, deferWrites = false) => {
    const asyncApiFilesFromDocsConfig = await getAsyncApiFilesFromConfig(docsConfig, localSchema);
    const pagesAcc = {};
    const writes = [];
    const planWrites = writeFiles && (deferWrites || (graphqlPages != null && Object.keys(graphqlPages).length > 0));
    const { newNav, newAsyncApiFiles } = await generateAsyncApiFromDocsConfig(docsConfig.navigation, asyncApiFiles, pagesAcc, {
        overwrite: true,
        writeFiles,
        targetDir,
        localSchema,
        ...(planWrites
            ? {
                writeFile: (filename, content) => {
                    writes.push({ filename, content });
                },
            }
            : {}),
    });
    const flushWrites = async () => {
        await Promise.all(writes.map(({ filename, content }) => fse.outputFile(filename, content)));
    };
    if (graphqlPages) {
        assertNoGeneratedRouteCollisions({ label: 'GraphQL', pages: graphqlPages }, { label: 'AsyncAPI', pages: pagesAcc });
    }
    if (!deferWrites)
        await flushWrites();
    return {
        newDocsConfig: { ...docsConfig, navigation: newNav },
        pagesAcc,
        asyncApiFiles: [...asyncApiFiles, ...asyncApiFilesFromDocsConfig, ...newAsyncApiFiles],
        flushWrites,
    };
};
